-- AND / OR drop an operand only next to an operand SQLite marks
-- EP_IsTrue / EP_IsFalse: a 32-bit integer literal or TRUE / FALSE. A
-- constant that merely folds to 0 / 1 (`('%' = 5)`, `-0`, 4294967296)
-- leaves both operands evaluated, so a raising sibling raises.
SELECT abs(-9223372036854775808) AND 0;
SELECT abs(-9223372036854775808) AND ('%' = -9223372036854775808);
SELECT (abs(-9223372036854775808) + 1) AND ('%' = 5);
SELECT ((abs(-9223372036854775808) + 1) AND ('%' = 5)) IS NOT NULL;
SELECT (abs(-9223372036854775808) AND 0) IS NULL;
SELECT (abs(-9223372036854775808) OR 1) IS NULL;
SELECT 0 AND abs(-9223372036854775808);
SELECT (1 = 2) AND abs(-9223372036854775808);
SELECT abs(-9223372036854775808) IS NOT NULL;
SELECT (abs(-9223372036854775808) + 1) IS NULL;
SELECT coalesce(1, abs(-9223372036854775808));
SELECT CASE WHEN 1 THEN 2 ELSE abs(-9223372036854775808) END;
SELECT typeof(abs(-9223372036854775808));
SELECT 1 FROM (SELECT 1) WHERE 0 AND abs(-9223372036854775808);
CREATE TABLE ao(x INTEGER);
INSERT INTO ao VALUES (1), (2);
SELECT x FROM ao WHERE abs(-9223372036854775808) AND (1 = 2);
SELECT x FROM ao WHERE (1 = 2) AND abs(-9223372036854775808);
SELECT x FROM ao WHERE x > 0 AND (abs(x - 9223372036854775807 - 2) OR (1 = 1));
SELECT (abs(x - 9223372036854775807 - 2) OR (2 > 1)) FROM ao;
SELECT x, (x OR (2 > 1)), (x AND (2 < 1)), (NULL AND (2 < 1)) FROM ao;
SELECT ((abs(-9223372036854775808) AND +0)) IS NULL;
SELECT (abs(-9223372036854775808) AND -0) IS NULL;
SELECT count(*) FROM ao GROUP BY x HAVING (1 = 1) OR abs(-9223372036854775808);
SELECT x FROM ao WHERE 1 = 1 AND x = 2;
SELECT max(x) AND (3 = 4) FROM ao;
SELECT (abs(-9223372036854775808) AND 4294967296) IS NULL;
SELECT (abs(-9223372036854775808) OR FALSE) IS NULL;
SELECT (abs(-9223372036854775808) AND FALSE) IS NULL;
SELECT (abs(-9223372036854775808) AND TRUE) IS NULL;
SELECT x FROM ao WHERE x AND 4294967296;
SELECT x FROM ao WHERE x OR 0;
